import type { ChatIndexEntry } from "@/server/domain/chat";
import { foldChatText } from "@/server/domain/chat-ai";
import type { ChatMatch } from "./chat-matcher";

const stop = new Set("la va cua thi ma co cho ve voi mot nhung cac duoc nao gi khi sao the nao toi minh ban bac oi hay xin hoi biet ke noi toi do ra".split(" "));
function tokens(text: string): Set<string> {
  const folded = foldChatText(text).replace(/\bcmtt\b/g, "cach mang thang tam").replace(/\bcmt8\b/g, "cach mang thang tam")
    .replace(/\bvn\b/g, "viet nam").replace(/\bhcm\b/g, "ho chi minh");
  return new Set((folded.match(/[a-z0-9]+/g) || []).filter(word => !stop.has(word)));
}
// Broad lexical retrieval expands beyond legacy top 3; it never changes exact/Fuse thresholds.
export function retrieveAiCandidates(message: string, index: ChatIndexEntry[], legacy: ChatMatch, limit: number): ChatIndexEntry[] {
  const query = tokens(message);
  const documents = index.map(entry => ({ entry, words: tokens([entry.canonicalQuestion, ...entry.aliases].join(" ")) }));
  const frequency = new Map<string, number>();
  for (const { words } of documents) for (const word of words) frequency.set(word, (frequency.get(word) || 0) + 1);
  const ranked = documents.map(({ entry, words }) => {
    const common = [...query].filter(word => words.has(word));
    const score = common.reduce((sum, word) => sum + Math.log(1 + index.length / (frequency.get(word) || 1)), 0) / Math.sqrt(words.size || 1);
    return { entry, score, common: common.length };
  }).filter(row => row.common >= Math.min(2, query.size) && row.common > 0)
    .sort((a, b) => b.score - a.score || a.entry.questionId.localeCompare(b.entry.questionId));
  const ids = legacy.type === "suggest" ? legacy.suggestions.map(row => row.questionId) : [];
  const entries = [...ids.map(id => index.find(row => row.questionId === id)).filter((row): row is ChatIndexEntry => !!row), ...ranked.map(row => row.entry)];
  return [...new Map(entries.map(row => [row.questionId, row])).values()].slice(0, limit);
}
